-- Language-neutral course content. Existing published-content RLS policies remain in force.
insert into public.courses (slug,title,description,language,accent,sort_order,is_published)
values ('programming-fundamentals','Programming Fundamentals','Learn transferable algorithms and pseudocode.','Language-neutral','#6f6ade',0,true)
on conflict (slug) do update set title=excluded.title,description=excluded.description,language=excluded.language,accent=excluded.accent,sort_order=excluded.sort_order,is_published=excluded.is_published;

insert into public.units (course_id,slug,title,description,theme,sort_order,is_published)
select id,'thinking-trail','Thinking Trail','Learn the logic before choosing a language.','fundamentals',1,true from public.courses where slug='programming-fundamentals'
on conflict (course_id,slug) do update set title=excluded.title,description=excluded.description,theme=excluded.theme,sort_order=excluded.sort_order,is_published=excluded.is_published;

insert into public.lessons (unit_id,slug,title,subtitle,lesson_type,icon,xp_reward,duration_minutes,sort_order,is_published)
select u.id,v.slug,v.title,v.subtitle,v.lesson_type,v.icon,v.xp_reward,v.duration_minutes,v.sort_order,true
from public.units u join public.courses c on c.id=u.course_id
cross join jsonb_to_recordset($fund_lessons$[{"slug":"fund-algorithms","title":"Algorithmic Thinking","subtitle":"Solve problems with clear steps","lesson_type":"lesson","icon":"🧭","xp_reward":30,"duration_minutes":6,"sort_order":1},{"slug":"fund-programming","title":"Introduction to Programming","subtitle":"Discover input, processing and output","lesson_type":"lesson","icon":"💡","xp_reward":30,"duration_minutes":6,"sort_order":2},{"slug":"fund-variables","title":"Variables","subtitle":"Store and update named values","lesson_type":"lesson","icon":"📦","xp_reward":30,"duration_minutes":6,"sort_order":3},{"slug":"fund-types","title":"Data Types","subtitle":"Distinguish text, numbers and booleans","lesson_type":"lesson","icon":"🧩","xp_reward":30,"duration_minutes":6,"sort_order":4},{"slug":"fund-operators","title":"Operators & Expressions","subtitle":"Calculate and compare","lesson_type":"lesson","icon":"➕","xp_reward":30,"duration_minutes":6,"sort_order":5},{"slug":"fund-conditions","title":"Conditional Decisions","subtitle":"Choose between IF and ELSE","lesson_type":"lesson","icon":"🔀","xp_reward":35,"duration_minutes":8,"sort_order":6},{"slug":"fund-loops","title":"Loops & Repetition","subtitle":"Repeat instructions safely","lesson_type":"lesson","icon":"🔁","xp_reward":35,"duration_minutes":8,"sort_order":7},{"slug":"fund-functions","title":"Functions","subtitle":"Reuse a set of instructions","lesson_type":"lesson","icon":"🛠️","xp_reward":40,"duration_minutes":8,"sort_order":8},{"slug":"fund-lists","title":"Arrays & Lists","subtitle":"Store and process collections","lesson_type":"lesson","icon":"🗂️","xp_reward":40,"duration_minutes":8,"sort_order":9},{"slug":"fund-mini-project","title":"Final Logic Challenge","subtitle":"Design a score counter in pseudocode","lesson_type":"project","icon":"🚀","xp_reward":90,"duration_minutes":12,"sort_order":10}]$fund_lessons$::jsonb) as v(slug text,title text,subtitle text,lesson_type text,icon text,xp_reward int,duration_minutes int,sort_order int)
where c.slug='programming-fundamentals' and u.slug='thinking-trail'
on conflict (slug) do update set unit_id=excluded.unit_id,title=excluded.title,subtitle=excluded.subtitle,lesson_type=excluded.lesson_type,icon=excluded.icon,xp_reward=excluded.xp_reward,duration_minutes=excluded.duration_minutes,sort_order=excluded.sort_order,is_published=excluded.is_published;

