at data type is \"Amara\"?","code_snippet":null,"options":["String","Integer","Boolean","List"],"placeholder":null,"hint":"Review the explanation and pseudocode example.","explanation":"Apply the idea, not a particular language's syntax.","sort_order":1},{"lesson_slug":"fund-types","exercise_key":"fund-types-q2","exercise_type":"choice","eyebrow":"Choose the answer","prompt":"What data type represents TRUE or FALSE?","code_snippet":null,"options":["Boolean","String","Integer","Decimal"],"placeholder":null,"hint":"Review the explanation and pseudocode example.","explanation":"Apply the idea, not a particular language's syntax.","sort_order":2},{"lesson_slug":"fund-types","exercise_key":"fund-types-q3","exercise_type":"text","eyebrow":"Complete the concept","prompt":"What common data type holds a whole number like 15?","code_snippet":null,"options":null,"placeholder":"Type your answer","hint":"Review the explanation and pseudocode example.","explanation":"Apply the idea, not a particular language's syntax.","sort_order":3},{"lesson_slug":"fund-operators","exercise_key":"fund-operators-q1","exercise_type":"choice","eyebrow":"Choose the answer","prompt":"What is 8 + 4 × 2?","code_snippet":null,"options":["16","24","20","12"],"placeholder":null,"hint":"Review the explanation and pseudocode example.","explanation":"Apply the idea, not a particular language's syntax.","sort_order":1},{"lesson_slug":"fund-operators","exercise_key":"fund-operators-q2","exercise_type":"choice","eyebrow":"Choose the answer","prompt":"Does 12 >= 10 evaluate to TRUE or FALSE?","code_snippet":null,"options":["TRUE","FALSE","12","10"],"placeholder":null,"hint":"Review the explanation and pseudocode example.","explanation":"Apply the idea, not a particular language's syntax.","sort_order":2},{"lesson_slug":"fund-operators","exercise_key":"fund-operators-q3","exercise_type":"text","eyebrow":"Complete the concept","prompt":"Which mathematical symbol means multiplication?","code_snippet":null,"options